"""Bounded, read-only discovery and retry of paused A→Z Astra review tasks.

Never bypasses a review, never writes model database, never touches trading.
Installed by capability-scoped projectexecutor in Prediction runtime.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import re
import sqlite3
import subprocess

CAMPAIGNS = Path.home() / ".local/share/prediction-project-executor/campaigns"
ID_RE = re.compile(r"^A2Z-[A-Za-z0-9_-]{1,120}$")
RETRY_STATES = {"PAUSED_USAGE_LIMIT", "WAITING_RETRY"}
ASTRA_PHASES = {"ASTRA_PREBUILD", "ASTRA_POSTBUILD", "SUPERVISOR"}
MAX_RETRIES_PER_TICK = 12


def candidates(root: Path):
    """Only already-enqueued reviewed requests with a real matching task row."""
    for campaign in sorted(root.iterdir()) if root.is_dir() else ():
        if not campaign.is_dir():
            continue
        db = campaign / "models/runtime.sqlite"
        requests = campaign / "requests"
        if not db.is_file() or not requests.is_dir():
            continue
        try:
            connection = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
        except sqlite3.Error:
            continue
        try:
            for path in sorted(requests.glob("*.json")):
                tid = path.stem
                if not ID_RE.fullmatch(tid):
                    continue
                if (campaign / "model_results" / path.name).exists():
                    continue
                try:
                    request = json.loads(path.read_text(encoding="utf-8"))
                    if request.get("task_id") != tid or request.get("phase") not in ASTRA_PHASES:
                        continue
                    if any(request.get(k) is not False for k in ("live_trading", "paid_actions", "wallet_actions")):
                        continue
                    if not str(request.get("route_task_id", "")).startswith("SESSION-ROUTE-"):
                        continue
                    row = connection.execute("select status from tasks where id=?", (tid,)).fetchone()
                except (OSError, ValueError, sqlite3.Error):
                    continue
                if row and row[0] in RETRY_STATES:
                    yield tid, row[0]
        finally:
            connection.close()


def tick(root: Path, *, run=subprocess.run):
    sent = 0
    for tid, status in candidates(root):
        if sent >= MAX_RETRIES_PER_TICK:
            break
        unit = f"prediction-a2z-v4-model@{tid}.service"
        # Existing per-task service uses the canonical reviewer and usage guards.
        result = run(["systemctl", "--user", "start", unit],
                     capture_output=True, text=True, timeout=120, check=False)
        print(json.dumps({"task_id": tid, "previous_status": status,
                          "service_rc": result.returncode}, sort_keys=True), flush=True)
        sent += 1
    print(f"A2Z_ASTra_RETRY_SWEEP scanned={sent} max={MAX_RETRIES_PER_TICK}", flush=True)
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--campaign-root", type=Path, default=CAMPAIGNS)
    args = parser.parse_args()
    return tick(args.campaign_root)


if __name__ == "__main__":
    raise SystemExit(main())
